import json
p='mendelian-randomization-runs/mr-20261010033028-8ebf5b45e76c/output/mendelian-randomization-run.json'
d=json.load(open(p))
def walk(o,pre='',depth=0):
    if depth>2: return
    if isinstance(o,dict):
        for k,v in o.items():
            if isinstance(v,(dict,list)):
                print(' '*depth*2+f'{pre}{k}: <{type(v).__name__} len={len(v)}>')
                walk(v,pre='',depth=depth+1)
            else:
                s=json.dumps(v,ensure_ascii=False)
                print(' '*depth*2+f'{pre}{k} = {s[:200]}')
    elif isinstance(o,list):
        for i,v in enumerate(o[:3]):
            walk(v,pre=f'[{i}].',depth=depth+1)
walk(d)
