mkdir -p /workspace/skill-closure/managed-results && cd /workspace && cat > /tmp/scan.py <<'PY'
import json,hashlib,os,glob

jobs = {
 'bibliometric_analysis': 'bibliometric-analysis-runs/.jobs/bibliometric-20261010033028-fd3433d170d6.json',
 'mendelian_randomization': None,
 'peer_review': 'peer-review-runs/.jobs/review-20261010033028-fe9e486d646a.json',
 'meta_analysis': 'meta-analysis-runs/.jobs/meta-20261010033028-fb4b4f173d3e.json',
 'research_topic_selection': 'research-topic-runs/.jobs/topic-20261010040140-8c052bbf36b9.json',
}
def sha(p):
    h=hashlib.sha256()
    with open(p,'rb') as f:
        for b in iter(lambda:f.read(1<<20),b''): h.update(b)
    return h.hexdigest()

out={}
for k,p in jobs.items():
    rec={}
    if p is None:
        out[k]={'note':'no queue record path configured in this scan'}
        continue
    d=json.load(open(p))
    rec['status']=d.get('status'); rec['jobId']=d.get('jobId'); rec['kind']=d.get('kind')
    rec['updatedAt']=d.get('updatedAt'); rec['elapsedSeconds']=d.get('elapsedSeconds')
    rec['progress']=d.get('progress'); rec['request']=d.get('request') or {'topic':d.get('topic'),'outputLanguage':d.get('outputLanguage')}
    rec['modules']=d.get('modules'); rec['degraded']=d.get('degraded')
    rec['sourcesNotUsed']=d.get('sourcesNotUsed'); rec['returnCode']=d.get('returnCode')
    rec['sourceEvidence']=d.get('sourceEvidence')
    rec['requestSha256']=d.get('requestSha256') or d.get('requestDigest')
    rec['artifact_count_declared']=len(d.get('artifacts') or [])
    art=[]
    for a in (d.get('artifacts') or []):
        pa=a.get('path')
        e={'path':pa,'kind':a.get('kind'),'declared_bytes':a.get('bytes'),'declared_sha256':a.get('sha256')}
        if pa and os.path.exists(pa):
            e['present']=True; e['bytes']=os.path.getsize(pa); e['sha256']=sha(pa)
            e['match']= (e['sha256']==e['declared_sha256']) if a.get('sha256') else None
        else:
            e['present']=pa and os.path.exists(pa)
        art.append(e)
    # also audit receipt artifacts
    ar=(d.get('auditReceipt') or {}).get('artifacts')
    if ar:
        rec['auditReceipt_artifacts']=ar
    rec['artifacts']=art
    out[k]=rec
json.dump(out,open('/tmp/scan.json','w'),ensure_ascii=False,indent=1)
for k,v in out.items():
    if 'artifacts' in v:
        miss=[a['path'] for a in v['artifacts'] if not a.get('present')]
        mism=[a['path'] for a in v['artifacts'] if a.get('match') is False]
        print(k, v['status'], 'declared',v['artifact_count_declared'],'missing',len(miss),'hashmismatch',len(mism))
        for m in mism[:5]: print('   MISMATCH',m)
        for m in miss[:5]: print('   MISSING',m)
    else: print(k, v)
PY
