#!/usr/bin/env python3
"""Protected-set check for the humanizer pass.

Compares a before/after pair of the reading records on everything the humanizer
pass must not move: digit runs, hex digests, byte counts, file and identifier
tokens. Paths come from the command line; without arguments it compares each
record against the copy kept beside it.
"""
import re, sys, os, json

TOKEN = re.compile(r'[A-Za-z0-9_.:\-]+')
NUM = re.compile(r'\d+(?:[.,]\d+)*')

def bag(text):
    return {
        'numbers': sorted(NUM.findall(text)),
        'tokens': sorted(t for t in TOKEN.findall(text) if any(c.isdigit() for c in t)),
    }

def norm(lines):
    return '\n'.join(sorted(l.strip() for l in lines if l.strip()))

def compare(before, after):
    b, a = bag(before), bag(after)
    out = []
    for k in ('numbers', 'tokens'):
        missing = list(b[k]); extra = list(a[k])
        for x in list(missing):
            if x in extra:
                missing.remove(x); extra.remove(x)
        if missing: out.append((k, 'lost', missing[:20]))
        if extra: out.append((k, 'added', extra[:20]))
    return out

if __name__ == '__main__':
    pairs = []
    if len(sys.argv) == 3:
        pairs = [(sys.argv[1], sys.argv[2])]
    else:
        here = os.path.dirname(os.path.abspath(__file__))
        d = os.path.join(here, 'managed-results')
        for f in sorted(x for x in os.listdir(d) if x.endswith('.json')):
            pairs.append((os.path.join(d, f), os.path.join(d, f)))
    bad = 0
    if len(sys.argv) == 3:
        diffs = compare(open(sys.argv[1]).read(), open(sys.argv[2]).read())
        print(os.path.basename(sys.argv[1]), 'diffs:', diffs or 'none')
        bad = len(diffs)
    else:
        base = '/tmp/hb'
        for cur, _ in pairs:
            backup = os.path.join(base, os.path.basename(cur))
            if not os.path.exists(backup):
                print('no backup for', cur); continue
            diffs = compare(open(backup).read(), open(cur).read())
            print(os.path.basename(cur), 'protected-set diffs:', diffs or 'none')
            bad += len(diffs)
    sys.exit(1 if bad else 0)
